r=Robot();o=r.get_obs(depth=True,video='none');s=r.spec();cam='egocentric_mirrored_camera';K=np.array(s['cameras'][cam]['intrinsic_cv']);E=np.array(o.meta['cameras'][cam]['extrinsic_cv']);inv=np.linalg.inv(np.vstack([E,[0,0,0,1]]));C=inv[:3,3];
for u,v in [(495,280),(495,270),(495,290),(468,282),(520,280)]:
