 print((u,v),round(float(d),3),np.round(w[:3],3),np.round(g,3))
# candidate side orientation q = Ry(-90)*qdown
qd=np.array([0,-2**-.5,2**-.5,0]);qy=np.array([2**-.5,0,-2**-.5,0]);w,x,y,z=qy; a,b,c,d=qd; q=np.array([w*a-x*b-y*c-z*d,w*b+x*a+y*d-z*c,w*c-x*d+y*a+z*b,w*d+x*c-y*b+z*a]);print('qside',q)
qnow=np.asarray(o.meta['proprio']['now'][:7]);
for p in [(.50,.08,.05),(.53,.08,.05),(.55,.08,.05),(.50,.08,.10),(.60,.08,.15)]:
 ans=r.ik({'tcp':[*p,*q]},seed=qnow);print(p,ans['ok'],ans['error']['tcp'],np.round(ans['q'],2))
